<?php defined('BASEPATH') or exit('No direct script access allowed');$c=$context;$addr=trim(implode('، ',array_filter([$c['address']??'',$c['city']??'',$c['state']??'',$c['zip']??''])));?><!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><title>رسید ورود کالای مرجوعی</title><style>body{font-family:Tahoma,Arial,sans-serif;color:#111;margin:28px;direction:rtl}h1{font-size:22px;margin:0}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #111;padding-bottom:14px}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.box{border:1px solid #bbb;border-radius:8px;padding:10px}.box small{display:block;color:#666;margin-bottom:5px}table{width:100%;border-collapse:collapse;margin-top:14px}th,td{border:1px solid #aaa;padding:8px;text-align:right}th{background:#f2f2f2}.sign{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:70px}.sign div{text-align:center;border-top:1px solid #333;padding-top:10px}.note{background:#f7f7f7;border:1px solid #ccc;padding:10px;margin-top:16px}.no-print{margin-bottom:18px}@media print{.no-print{display:none}body{margin:10mm}}</style></head><body><div class="no-print"><button onclick="window.print()">چاپ رسید ورود مرجوعی</button> <a href="<?php echo admin_url('sales_delivery_flow/return_invoice/'.$invoice->id);?>">بازگشت به مرجوعی</a></div><div class="head"><div><h1>رسید ورود کالای مرجوعی به انبار</h1><div>فاکتور شماره <?php echo html_escape($invoice->number);?></div></div><div><b>شماره مرجوعی:</b> <?php echo html_escape($return['return_no']);?><br><b>تاریخ ورود:</b> <?php echo html_escape($return['return_date']);?></div></div><div class="meta"><div class="box"><small>مشتری</small><b><?php echo html_escape($c['company']??'-');?></b></div><div class="box"><small>شماره تماس</small><b><?php echo html_escape($c['phonenumber']??'-');?></b></div><div class="box"><small>وضعیت مالی فاکتور</small><b><?php echo html_escape($c['payment_state']??'-');?></b></div></div><div class="box"><small>نشانی مشتری</small><b><?php echo html_escape($addr?:'-');?></b></div><h3>اقلام برگشتی و واردشده به انبار</h3><table><thead><tr><th>ردیف</th><th>شرح کالا</th><th>تعداد مرجوعی</th><th>قیمت واحد</th><th>تخفیف سهم ردیف</th><th>مبلغ</th><th>انبار</th></tr></thead><tbody><?php foreach($lines as $k=>$l){?><tr><td><?php echo $k+1;?></td><td><?php echo html_escape($l['description']);?></td><td><?php echo (float)$l['qty'];?></td><td><?php echo app_format_money($l['unit_price'],'');?></td><td><?php echo (float)$l['discount_amount']>0?app_format_money($l['discount_amount'],''):'—';?></td><td><?php echo app_format_money($l['line_total'],'');?></td><td><?php echo (int)$l['warehouse_id'];?></td></tr><?php }?></tbody></table><div class="note"><b>علت مرجوعی:</b> <?php echo html_escape($return['reason']?:'-');?><br><b>توضیحات:</b> <?php echo nl2br(html_escape($return['note']?:'-'));?><br><b>ثبت موجودی:</b> اقلام فوق به موجودی انبار خروج مربوطه بازگردانده شده‌اند.</div><div class="sign"><div>امضاء مشتری / تحویل‌دهنده</div><div>امضاء مدیر نمایشگاه</div><div>امضاء حسابدار</div><div>امضاء انباردار</div></div></body></html>
